import React, { useEffect, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';
import { Card, Grid, Button, Typography, Divider, Box, MenuItem, FormControl, InputLabel, Select } from '@mui/material';
import GenerateToastConfig from '../../../components/toast-config/GenerateToastConfig';
import InputField from '../../../components/input/inputField';
import { axios } from '../../../utils/axios';
import { useMyContext } from '../../provider';
import Iconify from '../../../components/iconify';
import useResponsive from '../../../hooks/useResponsive';

const EditUserReport = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const queryParams = new URLSearchParams(location.search);
  const userReportIds = queryParams.get('ids');
  const { i18 } = useMyContext();
  const isMobile = useResponsive('down', 'sm')
  // const [userReportData, setUserReportData] = useState([]);
  const [adminComment, setAdminComment] = useState('');
  const [reportStatus, setReportStatus] = useState('');

  const fetchData = async () => {
    try {
      const url = `module/report/listing/${userReportIds}`;
      const response = await axios.get(url);
      if (response?.status === 200) {
        const { adminComments, status } = response?.data?.data?.reportDetails[0];
        // setUserReportData(response?.data?.data?.reportDetails[0]);
        setAdminComment(adminComments);
        setReportStatus(status);
      }
    } catch (error) {
      GenerateToastConfig(error.message);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const backToRouter = () => {
    navigate('/dashboard/userReport');
  };

  const updateUserReport = async () => {
    try {
      const urlencoded = new URLSearchParams();
      urlencoded.append('status', reportStatus);
      urlencoded.append('comments', adminComment);
  
      const response = await axios.put(`module/report/update/status/${userReportIds}`, urlencoded);
      if (response?.status === 200) {
        GenerateToastConfig('Report updated successfully', 'success');
        backToRouter()
      }
    } catch (error) {
      GenerateToastConfig(error?.response?.data?.message || "Error Processing request", 'error');
    }
  };
  
  return (
    <>
      <Helmet>
        <title>Edit User Report | Admin Panel</title>
      </Helmet>
      <Card>
        <Grid container sx={{ padding: '10px 30px', margin: '10px 0px' }}>
          <Grid container item justifyContent="space-between" alignItems="center" sx={{ marginRight: '10px' }}>
            <Box sx={{ display: 'flex', alignItems: 'center' }}>
              <Box
                sx={{
                  width: '37px',
                  height: '37px',
                  background: '#FF5A60',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  borderRadius: '50%',
                  cursor: 'pointer',
                }}
                onClick={backToRouter}
              >
                <Iconify icon="mdi:arrow-left" width={24} height={24} color="white" />
              </Box>
              <Typography variant="h6" sx={{ marginLeft: '10px' }}>
                {i18?.ACCOUNTSTITLE?.EDIT_USER_REPORT || 'Edit User Report'}
              </Typography>
            </Box>
          </Grid>
        </Grid>

        <Divider sx={{ backgroundColor: '#333', margin: '10px 0px' }} />
        <Grid container sx={{ padding: '10px 30px' }}>
          <Grid item xs={6} sx={{ padding: '10px 50px 10px 0px' }}>
            <InputField
              value={adminComment}
              name="adminComment"
              label={i18?.ACCOUNTSTITLE?.COMMENTS|| 'Comments'}
              
              onChange={(e) => setAdminComment(e.target.value)}
              sx={{
                margin: '10px 0px',
                width: '100%',
                '& .MuiInputBase-input.MuiOutlinedInput-input': {
                  padding: '10.5px 14px'
                },
              }}
              type="text"
              required
            />
          </Grid>
          <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px 10px 0px' : '0px 5px' }}>
            <InputLabel sx={{ color: "#2B3343" }} id="status-select-label">
              {i18?.ACCOUNTSTITLE?.STATUS || "Status"}
            </InputLabel>
            <FormControl sx={{ marginTop: '10px' }} fullWidth>
              <Select
                labelId="status-select-label"
                id="status-select"
                sx={{
                  width: '100%',
                  '& .MuiInputBase-input.MuiOutlinedInput-input': {
                    padding: '10.5px 14px',
                  },
                }}
                value={reportStatus}
                onChange={(e) => setReportStatus(e.target.value)}
                required
              >
                <MenuItem value="inReview">In Review</MenuItem>
                <MenuItem value="resolved">Resolved</MenuItem>
                <MenuItem value="rejected">Rejected</MenuItem>
              </Select>
            </FormControl>
          </Grid>

        </Grid>

        <Divider sx={{ backgroundColor: '#333', margin: '10px 0px 10px 0px', width: '100%' }} />
        <Grid container justifyContent="flex-end" sx={{ padding: '10px 30px', margin: '10px 0px' }}>
          <Button
            sx={{
              padding: '10px 58px',
              background: '#FF5A60',
              '&:hover': {
                background: '#FF4A50',
              },
            }}
            variant="contained"
            onClick={updateUserReport}
            disabled={!adminComment}
          >
            {i18?.ACCOUNTSTITLE?.UPDATE || 'Update'}
          </Button>
        </Grid>
      </Card>
    </>
  );
};

export default EditUserReport;
